<?php elseif($section==='email'):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="email"><?php foreach(['host','port','username','sender_email','sender_name'] as $key):?><?=field($key,__('manor.smtp_'.$key),$smtp[$key],$key==='sender_email'?'email':($key==='port'?'number':'text'),!in_array($key,['host','username'],true))?><?php endforeach?><label><?=me(__('manor.smtp_encryption'))?><select name="encryption"><?php foreach(['tls','ssl','none'] as $enc):?><option <?=$smtp['encryption']===$enc?'selected':''?>><?=$enc?></option><?php endforeach?></select></label><label><?=me(__('manor.smtp_transport'))?><select name="transport"><option value="smtp" <?=$smtp['transport']==='smtp'?'selected':''?>>SMTP</option><option value="log" <?=$smtp['transport']==='log'?'selected':''?>><?=me(__('manor.log_only'))?></option></select></label><?=field('password',__('manor.smtp_password'),'','password',false)?><p><?=me(__($smtp['password_saved']?'manor.password_saved_hidden':'manor.no_password_saved'))?></p><label class="check"><input type="checkbox" name="clear_password" value="1"><?=me(__('manor.clear_password'))?></label><button><?=me(__('manor.save_settings'))?></button></form><div class="panel"><h2><?=me(__('manor.test_email'))?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="test_email"><?=field('recipient',__('manor.test_recipient'),\App\Engine\Auth::user()['email'],'email')?><button><?=me(__('manor.send_test_email'))?></button></form><?php if($test_result):?><p role="status"><?=me(__($test_result['success']?'manor.smtp_test_success':($test_result['log_only']?'manor.smtp_test_log':'manor.smtp_test_failed')))?></p><?php endif?></div><h2><?=me(__('manor.mail_logs'))?></h2><div class="table-scroll"><table><tr><th><?=me(__('manor.date'))?></th><th><?=me(__('manor.status'))?></th><th><?=me(__('manor.error'))?></th></tr><?php foreach($mail_logs as $log):?><tr><td><?=me($log['sent_at'])?></td><td><?=me($log['status'])?></td><td><?=me